<?php/** * 生成图片服务 */namespace app\api\service\public;use app\api\service\CommService;use Exception;use OSS\OssClient;use support\exception\BusinessException;class ImagesService extends CommService{    protected $access_path;    protected $file_path;    protected $full_file_path;    public function __construct($param)    {        parent::_initialize($param);        $this->file_path = '/draw_img/';        $this->access_path = $_SERVER['REQUEST_SCHEME'] . '://' . $_SERVER['HTTP_HOST'] . $this->file_path;        $this->full_file_path = $_SERVER['DOCUMENT_ROOT'] . $this->file_path;    }    public function generateImages($words, $name = '', $upload_type = '')    {        if (empty($words)) {            throw new BusinessException('没有字符输入',401);        }        $fileName = ImagesService . phpmd5($words) . time() . ".png";        if ($name) {            $fileName = $name . ".png";        }        //设置字体样式        $font = ROOT_PATHS . "/font/AudiType-ExtendedBold_4.03.otf";//设置 英文字体样式        $font_size = 130;//设置字体大小        $imgWidth = 3000;        $imgHeight = 1400;        $img = imagecreatetruecolor($imgWidth, $imgHeight);//创建一个空白的背景        $bgcolor = imagecolorallocate($img, 255, 255, 255);//为图像定义背景颜色        imagefill($img, 0, 0, $bgcolor);//为图像绘画背景色//        $fontBox = imagettfbbox($font_size, 0, $font, $words);//获取文字所需的尺寸大小        //在图片上绘制文字//        $blue_color = imagecolorallocate($img, 0, 0, 0); //设置文字的颜色        //写入文字 (图片资源，字体大小，旋转角度，坐标x，坐标y，颜色，字体文件，内容)//        $text_width = ceil(($imgWidth - $fontBox[2]) / 2);//        $text_height = ceil(($imgHeight - $fontBox[1] - $fontBox[7]) / 2);        //字体加粗,复写三遍//        for ($i = 0; $i <= 3; $i++) {//            imagettftext($img, $font_size, 0, $text_width++, $text_height++, $blue_color, $font, $words);  //绘制文字//        }        //输出图片        if (!file_exists($this->full_file_path)) {            mkdir($this->full_file_path);        }        $this->data['img_url'] = $this->saveImg($img, $fileName, $upload_type);        return $this->data;    }    public function saveImg($img, $file_name, $upload_type = '')    {        $uploadConfig = sysconfig('upload');        if ($upload_type) {            $uploadConfig['upload_type'] = $upload_type;        }        $object = '2023audi' . $this->file_path . $file_name;// 设置文件名称(存储得文件夹+名称)        try {            imagepng($img, $this->full_file_path . $file_name);            //释放空间            imagedestroy($img);            switch ($uploadConfig['upload_type']) {                case 'alioss':                    //上传到阿里云oss                    $ossClient = new OssClient($uploadConfig['alioss_access_key_id'], $uploadConfig['alioss_access_key_secret'], $uploadConfig['alioss_endpoint']);                    $upload = $ossClient->uploadFile($uploadConfig['alioss_bucket'], $object, $this->full_file_path . $file_name);                    return $upload['info']['url'] ?? '';                default:                    return $this->access_path . $file_name;            }        } catch (Exception $e) {            throwError($e->getMessage());        }    }}